rules.suggestion:
1. 严禁在生产代码中禁用SSL证书校验；2. 使用Certificate Pinning绑定服务器证书或公钥；3. 移除所有调试用的证书绕过代码；4. 使用成熟的网络安全库，避免自定义TLS验证逻辑；5. 使用代码扫描工具检测证书校验绕过模式。

示例（Android - 错误的证书绕过）：
```java
// 极度危险！不要这样做
TrustManager[] trustAllCerts = new TrustManager[]{
    new X509TrustManager() {
        public void checkClientTrusted(X509Certificate[] chain, String authType) {}
        public void checkServerTrusted(X509Certificate[] chain, String authType) {}
        public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[0]; }
    }
};
```

示例（Android - 正确的Certificate Pinning）：
```kotlin
// 使用OkHttp CertificatePinner
val pinner = CertificatePinner.Builder()
    .add("api.example.com", "sha256/AAAAAAAAAAAAAAAAAAAAAAAAA=")
    .add("api.example.com", "sha256/BBBBBBBBBBBBBBBBBBBBBBBBB=")
    .build()

val client = OkHttpClient.Builder()
    .certificatePinner(pinner)
    .build()
```

1. 对所有深度链接参数进行严格的白名单校验；2. 使用Universal Links（iOS）/ App Links（Android）替代自定义URL Scheme；3. 对敏感操作的深度链接增加二次确认；4. 验证链接来源应用的签名（Android）；5. 限制深度链接可执行的操作范围；6. 对链接参数进行长度和格式限制。

示例（Android - Kotlin）：
```kotlin
// 安全处理深度链接
fun handleDeepLink(intent: Intent) {
    val uri = intent.data ?: return

    // 校验Scheme和Host
    val allowedHosts = setOf("transfer", "profile", "settings")
    if (uri.host !in allowedHosts) {
        Log.w("DeepLink", "Blocked unknown host: ${uri.host}")
        return
    }

    // 校验参数
    val amount = uri.getQueryParameter("amount")?.toDoubleOrNull()
    if (amount != null && amount > MAX_AMOUNT) {
        showConfirmationDialog(amount)  // 大额操作需确认
        return
    }
}
```

示例（iOS - Swift）：
```swift
// 安全处理Universal Links
func application(_ application: UIApplication,
    continue userActivity: NSUserActivity,
    restorationHandler: @escaping ([UIUserActivityRestoring]?) -> Void) -> Bool {

    guard userActivity.activityType == NSUserActivityTypeBrowsingWeb,
          let url = userActivity.webpageURL,
          let components = URLComponents(url: url, resolvingAgainstBaseURL: true)
    else { return false }

    // 校验域名
    guard components.host == "www.example.com" else { return false }

    // 白名单路径校验
    let allowedPaths = ["/transfer", "/profile"]
    guard allowedPaths.contains(components.path) else { return false }

    return handleRoute(components)
}
```

1. 仅在必要时启用JavaScript，并确保加载的内容可信；2. 禁止WebView加载外部URL（使用白名单）；3. 避免使用addJavascriptInterface，如必须使用，限制暴露的接口方法；4. 禁用不必要的WebView功能（文件访问、内容访问等）；5. 对WebView实施CSP（Content Security Policy）。

示例（Android - Kotlin）：
```kotlin
val webView = WebView(context).apply {
    settings.javaScriptEnabled = true  // 仅在必要时启用

    // 禁用不安全的功能
    settings.allowFileAccess = false
    settings.allowContentAccess = false
    settings.allowUniversalAccessFromFileURLs = false
    settings.allowFileAccessFromFileURLs = false

    // 安全处理WebView导航
    webViewClient = object : WebViewClient() {
        override fun shouldOverrideUrlLoading(
            view: WebView, request: WebResourceRequest
        ): Boolean {
            val url = request.url.toString()
            // 白名单校验
            val allowedDomains = listOf("api.example.com", "www.example.com")
            return !allowedDomains.any { url.contains(it) }
        }
    }
}
```

示例（iOS - Swift）：
```swift
let config = WKWebViewConfiguration()
// 不注入不必要的脚本
config.preferences.javaScriptEnabled = true
config.preferences.javaScriptCanOpenWindowsAutomatically = false

let webView = WKWebView(frame: .zero, configuration: config)
webView.navigationDelegate = self

// 限制导航范围
func webView(_ webView: WKWebView,
    decidePolicyFor navigationAction: WKNavigationAction,
    decisionHandler: @escaping (WKNavigationActionPolicy) -> Void) {

    let allowedHosts = ["www.example.com", "api.example.com"]
    if let host = navigationAction.request.url?.host,
       allowedHosts.contains(host) {
        decisionHandler(.allow)
    } else {
        decisionHandler(.cancel)
    }
}
```

1. 使用SQLCipher或WCDB等加密数据库方案；2. 对Realm使用内置加密功能；3. 使用平台提供的安全存储方案替代明文数据库；4. 加密密钥存储在硬件安全模块（Keychain/Keystore）中；5. 对数据库中的敏感字段实施字段级加密；6. 定期清理不再需要的本地数据。

示例（Android - Kotlin + SQLCipher）：
```kotlin
// 使用SQLCipher加密SQLite
val passphrase = net.sqlcipher.database.SQLiteOpenHelper.getBytes(
    getMasterKey()  // 从Keystore获取密钥
)
val db = SQLiteDatabase.openOrCreateDatabase(
    getDatabasePath("secure.db"),
    passphrase,
    null
)

// 使用WCDB（腾讯开源）
val database = WCBDatabase(
    path = databasePath,
    key = masterKey  // 加密密钥
)
```

示例（iOS - Swift + SQLCipher）：
```swift
// FMDB + SQLCipher
let db = FMDatabase(path: databasePath)
db.open(withFlags: SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE,
        vfs: nil)
try db.setKey(masterKey)  // 设置加密密钥

// 或使用GRDB + SQLCipher
var config = Configuration()
config.prepareDatabase { db in
    try db.usePassphrase(masterKey)
}
```

1. 使用平台原生的生物认证API（BiometricPrompt/LocalAuthentication），不要自行实现；2. 生物认证应与加密密钥绑定（CryptoObject），认证通过才能解密密钥；3. 避免简单的布尔值标记认证状态；4. 降级策略应保持同等安全级别，不允许降级为明显弱于生物认证的方式；5. 使用setAllowDeviceCredential(false)禁止设备凭证降级。

示例（Android - Kotlin）：
```kotlin
// 正确的生物认证 + 加密绑定
val biometricPrompt = BiometricPrompt(activity, executor,
    object : BiometricPrompt.AuthenticationCallback() {
        override fun onAuthenticationSucceeded(result: BiometricPrompt.AuthenticationResult) {
            // 使用CryptoObject中的加密密钥
            val crypto = result.cryptoObject
            val cipher = crypto?.cipher
            val decryptedToken = cipher?.doFinal(encryptedToken)
            // 使用解密后的Token，而不是简单的布尔标志
        }
    })

val promptInfo = BiometricPrompt.PromptInfo.Builder()
    .setTitle("身份验证")
    .setSubtitle("请使用指纹验证身份")
    .setNegativeButtonText("取消")
    .setAllowedAuthenticators(BIOMETRIC_STRONG)  // 仅允许强生物认证
    .setConfirmationRequired(true)
    .build()

// 使用CryptoObject绑定
biometricPrompt.authenticate(promptInfo, cryptoObject)
```

示例（iOS - Swift）：
```swift
import LocalAuthentication

func authenticateWithBiometrics(completion: @escaping (Bool, Error?) -> Void) {
    let context = LAContext()
    context.localizedCancelTitle = "使用密码"

    // 设置安全级别
    if #available(iOS 11.0, *) {
        // 不允许降级到设备密码
        context.evaluatedPolicy == .deviceOwnerAuthenticationWithBiometrics
    }

    var error: NSError?
    if context.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: &error) {
        context.evaluatePolicy(.deviceOwnerAuthenticationWithBiometrics,
            localizedReason: "请使用生物认证登录") { success, error in
            DispatchQueue.main.async {
                completion(success, error)
            }
        }
    }
}
```
